export function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
const rnd=rng(970401);
const surnames='김 이 박 최 정 강 조 윤 장 임 한 오 서 신 권 황 안 송 전 홍 유 고 문 양 손 배 백 허 남 심 노 하 주 성 차 우 구 민 진 엄'.split(' ');
const first='도 서 지 하 예 민 수 태 주 시 현 가 은 연 재 승 유 정 윤 다 세 소 채 호 영'.split(' ');
const lastM='준 우 현 민 진 성 호 원 훈 온 율 빈 찬 윤 혁 겸 규 선 석 웅'.split(' ');
const lastF='윤 은 서 아 연 린 원 진 현 영 민 정 솔 인 경 빈 주 수 이 유'.split(' ');
const names=new Set();
function person(role,gender,index,offset){
  let name;do{name=surnames[Math.floor(rnd()*surnames.length)]+first[Math.floor(rnd()*first.length)]+(gender==='F'?lastF:lastM)[Math.floor(rnd()*20)];}while(names.has(name));names.add(name);
  const skill=Math.round(42+rnd()*52),star=Math.round(15+rnd()*79),coop=Math.round(45+rnd()*53);
  const g1=GENRES[Math.floor(rnd()*GENRES.length)].id;let g2;do{g2=GENRES[Math.floor(rnd()*GENRES.length)].id;}while(g1===g2);
  const rate={writer:.9,director:1.5,lead:2.25,support:.62}[role];
  return{id:`p${offset+index}`,name,gender,role,age:Math.floor(24+rnd()*35),skill,star,coop,genres:[g1,g2],fee:Math.round((.15+Math.pow((skill+star)/160,2)*rate)*100)/100,trait:['현장에 강한','섬세한 해석의','새로운 시도를 즐기는','꾸준한 실력의','대중의 마음을 읽는','팀워크를 중시하는'][Math.floor(rnd()*6)]};
}
export const PEOPLE=[];
let offset=0;for(const [role,gender,count] of [['writer','M',100],['writer','F',100],['director','M',100],['director','F',100],['lead','M',200],['lead','F',200],['support','M',400],['support','F',400]]){for(let i=0;i<count;i++)PEOPLE.push(person(role,gender,i,offset));offset+=count;}
